// ─── Side label column (left or right) with connector lines
function LabelColumn({ hotspots, side, bounds, visible }) {
  const filtered = hotspots.filter((h) => h.anchor === side);

  // Function to convert percentage coordinates to pixel positions
  const toPx = (ix, iy) => {
    if (!bounds) return { x: 0, y: 0 };
    return {
      x: bounds.left + (ix / 100) * bounds.width,
      y: bounds.top + (iy / 100) * bounds.height,
    };
  };

  return (
    <div
      style={{
        position: "relative",
        width: 140,
        height: "100%",
        flexShrink: 0,
        opacity: visible ? 1 : 0,
        transition: "opacity 0.32s ease",
      }}
    >
      {/* Vertical pipe divider */}
      <div
        style={{
          position: "absolute",
          top: 0,
          bottom: 0,
          [side === "left" ? "right" : "left"]: 0,
          width: 2,
          background: "rgba(204, 0, 0, 0.6)",
          borderRadius: 1,
        }}
      />

      {/* SVG for connector lines */}
      {bounds && (
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
            overflow: "visible",
          }}
        >
          {filtered.map((h, i) => {
            const dotPos = toPx(h.ix, h.iy);

            // Calculate line start/end positions
            let startX, startY, endX, endY;

            if (side === "left") {
              // Line from label to dot (rightward from label to map)
              startX = 120; // Label area edge
              startY = dotPos.y;
              endX = dotPos.x - 8; // Just before the dot
              endY = dotPos.y;
            } else {
              // Line from label to dot (leftward from label to map)
              startX = 20; // Label area edge
              startY = dotPos.y;
              endX = dotPos.x + 8; // Just before the dot
              endY = dotPos.y;
            }

            return (
              <line
                key={i}
                x1={startX}
                y1={startY}
                x2={endX}
                y2={endY}
                stroke="#cc0000"
                strokeWidth="2"
                strokeDasharray="4 3"
                style={{
                  strokeLinecap: "round",
                }}
              />
            );
          })}
        </svg>
      )}

      {filtered.map((h, i) => {
        const topPct = h.iy;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              top: `${topPct}%`,
              transform: "translateY(-50%)",
              [side === "left" ? "right" : "left"]: 16,
              textAlign: side === "left" ? "right" : "left",
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              whiteSpace: "nowrap",
              zIndex: 10,
            }}
          >
            {/* Horizontal tick line toward the pipe */}
            <div
              style={{
                position: "absolute",
                top: "50%",
                transform: "translateY(-50%)",
                [side === "left" ? "right" : "left"]: -12,
                width: 8,
                height: 2,
                background: "#cc0000",
                borderRadius: 1,
              }}
            />
            <div
              style={{
                background: "rgba(0, 0, 0, 0.7)",
                backdropFilter: "blur(8px)",
                padding: "4px 12px",
                borderRadius: 20,
                border: "1px solid rgba(204, 0, 0, 0.3)",
              }}
            >
              <div
                style={{
                  fontSize: "clamp(14px, 1.4vw, 19px)",
                  fontWeight: 700,
                  color: "#ff6600",
                  lineHeight: 1.2,
                }}
              >
                {h.pct}
              </div>
              <div
                style={{
                  fontSize: "clamp(10px, 0.9vw, 12px)",
                  color: "rgba(255,255,255,0.85)",
                  marginTop: 2,
                  fontWeight: 500,
                }}
              >
                {h.label}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ─── Bottom label row (for bottom-anchored states) with connector lines
function BottomLabels({ hotspots, bounds, visible }) {
  const filtered = hotspots.filter((h) => h.anchor === "bottom");
  if (!filtered.length) return null;

  const toPx = (ix, iy) => {
    if (!bounds) return { x: 0, y: 0 };
    return {
      x: bounds.left + (ix / 100) * bounds.width,
      y: bounds.top + (iy / 100) * bounds.height,
    };
  };

  return (
    <div
      style={{
        position: "relative",
        display: "flex",
        justifyContent: "center",
        gap: 48,
        marginTop: 16,
        opacity: visible ? 1 : 0,
        transition: "opacity 0.32s ease",
        paddingTop: 8,
      }}
    >
      {/* SVG for connector lines from bottom labels */}
      {bounds && (
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
            overflow: "visible",
          }}
        >
          {filtered.map((h, i) => {
            const dotPos = toPx(h.ix, h.iy);

            // Calculate line positions for each label based on its container
            const labelElements = document.querySelectorAll(`[data-bottom-label="${h.label}"]`);
            if (labelElements.length > 0) {
              const labelRect = labelElements[0].getBoundingClientRect();
              const containerRect = labelElements[0].parentElement?.parentElement?.getBoundingClientRect();

              if (containerRect) {
                const startX = labelRect.left + labelRect.width / 2 - containerRect.left;
                const startY = labelRect.top - containerRect.top;

                return (
                  <line
                    key={i}
                    x1={startX}
                    y1={startY}
                    x2={dotPos.x}
                    y2={dotPos.y}
                    stroke="#cc0000"
                    strokeWidth="2"
                    strokeDasharray="4 3"
                    style={{
                      strokeLinecap: "round",
                    }}
                  />
                );
              }
            }
            return null;
          })}
        </svg>
      )}

      {filtered.map((h, i) => (
        <div
          key={i}
          data-bottom-label={h.label}
          style={{
            textAlign: "center",
            fontFamily: "'Inter','Helvetica Neue',sans-serif",
            background: "rgba(0, 0, 0, 0.7)",
            backdropFilter: "blur(8px)",
            padding: "6px 16px",
            borderRadius: 24,
            border: "1px solid rgba(204, 0, 0, 0.3)",
            minWidth: 100,
          }}
        >
          {/* Small upward tick */}
          <div
            style={{
              width: 2,
              height: 12,
              background: "#cc0000",
              margin: "0 auto 6px",
              borderRadius: 1,
            }}
          />
          <div
            style={{
              fontSize: "clamp(14px, 1.4vw, 19px)",
              fontWeight: 700,
              color: "#ff6600",
              lineHeight: 1.2,
            }}
          >
            {h.pct}
          </div>
          <div
            style={{
              fontSize: "clamp(10px, 0.9vw, 12px)",
              color: "rgba(255,255,255,0.85)",
              marginTop: 2,
              fontWeight: 500,
            }}
          >
            {h.label}
          </div>
        </div>
      ))}
    </div>
  );
}

// Update the main component to pass bounds to LabelColumn and BottomLabels
export default function GeographicSection() {
  const [openIndex, setOpenIndex] = useState(0);
  const [activeKey, setActiveKey] = useState("truck");
  const [hsVisible, setHsVisible] = useState(true);
  const [progress, setProgress] = useState(0);
  const [mapHeight, setMapHeight] = useState(0);

  const sectionRef = useRef(null);
  const mapContainerRef = useRef(null);
  const mapImgRef = useRef(null);

  const imgBounds = useImageBounds(mapImgRef, mapContainerRef);

  // Track map container height so label columns can match it
  useEffect(() => {
    if (!mapContainerRef.current) return;
    const ro = new ResizeObserver(() => {
      setMapHeight(mapContainerRef.current?.clientHeight || 0);
    });
    ro.observe(mapContainerRef.current);
    setMapHeight(mapContainerRef.current.clientHeight);
    return () => ro.disconnect();
  }, []);

  const switchMap = (newKey) => {
    if (newKey === activeKey) return;
    setHsVisible(false);
    setTimeout(() => {
      setActiveKey(newKey);
      setHsVisible(true);
    }, 320);
  };

  const handleSegmentClick = (index) => {
    const isOpen = openIndex === index;
    setOpenIndex(isOpen ? null : index);
    if (!isOpen) switchMap(SEGMENTS[index].mapKey);
  };

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      setProgress(clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1));
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const titleP = ease(clamp(progress / 0.2, 0, 1));
  const leftP = ease(clamp((progress - 0.2) / 0.25, 0, 1));
  const mapP = ease(clamp((progress - 0.2) / 0.3, 0, 1));

  const hotspots = MAP_DATA[activeKey];

  return (
    <div ref={sectionRef} style={{ height: "350vh", position: "relative" }}>
      <div
        style={{
          position: "sticky",
          top: 0,
          height: "135vh",
          overflow: "hidden",
          background: "black",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          padding: "72px 56px 40px",
        }}
      >
        {/* Background ellipse */}
        <div style={{ position: "absolute", top: 0, left: -450, zIndex: 0 }}>
          <img src="/assets/Ellipse.png" alt="" style={{ width: 900, height: 900 }} />
        </div>

        {/* Title */}
        <div
          style={{
            textAlign: "center",
            marginBottom: 8,
            opacity: titleP,
            transform: `translateY(${lerp(24, 0, titleP)}px)`,
          }}
        >
          <h2
            style={{
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              fontSize: "105px",
              fontWeight: 700,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
            }}
          >
            Geographic Risk
            <br />
            Concentration
          </h2>
          <p
            style={{
              color: "white",
              fontSize: 18,
              margin: "12px 0 0",
              fontFamily: "'Inter',sans-serif",
            }}
          >
            A breakdown of states with the highest risk rates across India.
          </p>
        </div>

        {/* Body grid: accordion left | map+labels right */}
        <div className="grid grid-cols-1 lg:grid-cols-[320px_1fr] gap-12 w-full max-w-[1200px] flex-1 mt-6">
          {/* ── Left panel: description + accordion ── */}
          <div
            style={{
              opacity: leftP,
              transform: `translateX(${lerp(-24, 0, leftP)}px)`,
              display: "flex",
              flexDirection: "column",
              gap: 20,
              paddingTop: 8,
            }}
          >
            <p
              style={{
                color: "white",
                fontSize: 16,
                lineHeight: 1.7,
                fontFamily: "'Inter',sans-serif",
                margin: 0,
                paddingLeft: 12,
              }}
            >
              Kerala records the highest risk rate in the country, with Maharashtra close behind,
              making them two of the highest risk concentration states across segments.
            </p>
            <p
              style={{
                color: "white",
                fontSize: 16,
                lineHeight: 1.7,
                fontFamily: "'Inter',sans-serif",
                margin: 0,
                paddingLeft: 12,
              }}
            >
              Another contributing factor behind this surge could be stronger crime reporting
              mechanisms in southern and western states. For example, in Kerala, many challans are
              automatically generated through AI-enabled monitoring cameras at traffic junctions.
            </p>

            {/* Accordion */}
            <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 10 }}>
              {SEGMENTS.map((item, i) => {
                const isOpen = openIndex === i;
                return (
                  <div key={i}>
                    <div
                      onClick={() => handleSegmentClick(i)}
